scripts.沙漠卖药人.txt:
	GetRandNum($Temp,0,4);
	If ($Temp == 0) @Talk0;
	If ($Temp == 1) @Talk1;
	If ($Temp == 2) @Talk2;
	If ($Temp == 3) @Talk3;
	Goto @Talk4;
	Return;
@Talk0:
	Say("沙漠卖药人：此处沙漠，环境甚是不好，可这周围总有些武林中人出没。到此卖药还颇有些收入。");
	BuyGoods("中级药品.ini");
	Return;
@Talk1:
	Say("沙漠卖药人：公子看看我的草药，买些随身携带，出门也有备无患。");
	Say("杨影枫：我且看看。", 2);
	BuyGoods("中级药品.ini");
	Return;
@Talk2:
	Say("杨影枫：可有好药卖予我些？", 2);
	Say("沙漠卖药人：好药自然是不缺，公子自挑吧。");
	BuyGoods("高级药品.ini");
	Return;
@Talk3:
	Say("沙漠卖药人：这座通天塔看去如此高大，看里面好似有人把守，至此多次倒没上去看过。");
	Say("杨影枫：你且卖药，做你的营生就好，别不小心就惹上了麻烦。", 2);
	Say("沙漠卖药人：那是那是！");
	BuyGoods("高级药品.ini");
	Return;
@Talk4:
	Say("沙漠卖药人：公子，近前看看我的草药，都是品质极佳啊！");
	Say("杨影枫：自卖当然自夸，看上去你的药也没有什么特别啊！", 2);
	Say("沙漠卖药人：卖药又不是卖奇珍异玩，哪要指望它特别来着，吃了有效就是好。");
	BuyGoods("高级药品.ini");
	Return;

traps.Trap01.txt:
	If ($Event == 2010) @2009;
	If ($Event == 2009) @2009;
	If ($Event == 3182) @L3182;

	FadeOut();
	SaveNpc();
	SaveObj();
	LoadMap("MAP_041_通天塔一层.map");
	LoadObj("map041_obj.obj");
	LoadNpc("map041.npc");
	SetPlayerPos(7, 170);
	SetPlayerDir(5);
	EnableNpcAI();
	FadeIn();
	Return;
	
@2009:
	FadeOut();
	SaveNpc();
	SaveObj();
	LoadMap("MAP_041_通天塔一层.map");
	LoadNpc("map041_1.npc");
	LoadObj("map041_obj.obj");
	SetPlayerPos(7, 170);
	SetPlayerDir(5);
	EnableNpcAI();
	FadeIn();
	Return;
	
@L3182:
	FadeOut();
	SaveNpc();
	SaveObj();
	LoadMap("MAP_041_通天塔一层.map");
	LoadObj("map041_obj.obj");
	LoadNpc("map041_FindNLZ.npc");
	If ($Have1 == 0) @Have1;
	Goto @Next1;

@Have1:
	SetMapTrap(10, "入口守卫对话.txt");
	Assign($Have1,1);
	Goto @Next1;	
	
@Next1:	
	DelObj("通天塔开关");
	//AddObj("遮挡物.ini",54,140,0);
	AddObj("Lock_1.ini",54,134,0);
	If ($Lock1 == 1)  @Opened;
	Goto @Next;

@Opened:
	OpenBox("通天塔开关");
	Goto @Next;	

@Next:
	SetPlayerPos(7, 170);
	SetPlayerDir(5);
	EnableNpcAI();
	FadeIn();
	//SetMapTrap(1,"");
	//SetMapTrap(2,"");
	SetTrap("map_040_沙漠",2,"");
	Return;

